static const char hc_py_50[] = "class A:\n\n    var = 132\n\n    def __init__(self):\n        self.var2 = 34\n\n    def meth(self, i):\n        return 42 + i\n\n\na = A()\nprint(hasattr(a, \"var\"))\nprint(hasattr(a, \"var2\"))\nprint(hasattr(a, \"meth\"))\nprint(hasattr(a, \"_none_such\"))\nprint(hasattr(list, \"foo\"))\n\nclass C:\n\n    def __getattr__(self, attr):\n        if attr == \"exists\":\n            return attr\n        elif attr == \"raise\":\n            raise Exception(123)\n        raise AttributeError\n\nc = C()\nprint(hasattr(c, \"exists\"))\nprint(hasattr(c, \"doesnt_exist\"))\n\n# ensure that non-AttributeError exceptions propagate out of hasattr\ntry:\n    hasattr(c, \"raise\")\nexcept Exception as er:\n    print(er)\n\ntry:\n    hasattr(1, b'123')\nexcept TypeError:\n    print('TypeError')\n\ntry:\n    hasattr(1, 123)\nexcept TypeError:\n    print('TypeError')\n";
static const char hc_py_51[] = "# test builtin hash function\n\nprint(hash(False))\nprint(hash(True))\nprint({():1}) # hash tuple\nprint({(1,):1}) # hash non-empty tuple\nprint(hash in {hash:1}) # hash function\nprint(type(hash(list.pop))) # hash checked function (mp_type_checked_fun)\nprint(type(hash([].pop))) # hash bound method\nprint(type(hash(object()))) # hash object instance\nprint(type(hash(super(object, object)))) # hash super\nprint(type(hash(classmethod(hash)))) # hash classmethod\nprint(type(hash(staticmethod(hash)))) # hash staticmethod\nprint(type(hash(iter(\"\")))) # hash string iterator\nprint(type(hash(iter(b\"\")))) # hash bytes iterator\nprint(type(hash(iter(range(0))))) # hash range iterator\nprint(type(hash(map(None, [])))) # hash map object\nprint(type(hash(zip([])))) # hash zip object\n\ndef f(x):\n    def g():\n        return x\n    return g\n\nprint(type(hash(f(1)))) # hash closure\n\ntry:\n    hash([])\nexcept TypeError:\n    print(\"TypeError\")\n\nclass A:\n    def __hash__(self):\n        return 123\n    def __repr__(self):\n        return \"a instance\"\n\nprint(hash(A()))\nprint({A():1})\n\n# all user-classes have default __hash__\nclass B:\n    pass\nhash(B())\n\n# if __eq__ is defined then default __hash__ is not used\nclass C:\n    def __eq__(self, another):\n        return True\ntry:\n    hash(C())\nexcept TypeError:\n    print(\"TypeError\")\n\n# __hash__ must return an int\nclass D:\n    def __hash__(self):\n        return None\ntry:\n    hash(D())\nexcept TypeError:\n    print(\"TypeError\")\n\n# __hash__ returning a bool should be converted to an int\nclass E:\n    def __hash__(self):\n        return True\nprint(hash(E()))\n";
