static const char hc_py_72[] = "# test builtin property\ntry:\n    property\nexcept:\n    print(\"SKIP\")\n    raise SystemExit\n\n# create a property object explicitly\nproperty()\nproperty(1, 2, 3)\n\n# use its accessor methods\np = property()\np.getter(1)\np.setter(2)\np.deleter(3)\n\n# basic use as a decorator\nclass A:\n    def __init__(self, x):\n        self._x = x\n\n    @property\n    def x(self):\n        print(\"x get\")\n        return self._x\n\na = A(1)\nprint(a.x)\n\ntry:\n    a.x = 2\nexcept AttributeError:\n    print(\"AttributeError\")\n\n# explicit use within a class\nclass B:\n    def __init__(self, x):\n        self._x = x\n\n    def xget(self):\n        print(\"x get\")\n        return self._x\n\n    def xset(self, value):\n        print(\"x set\")\n        self._x = value\n\n    def xdel(self):\n        print(\"x del\")\n\n    x = property(xget, xset, xdel)\n\nb = B(3)\nprint(b.x)\nb.x = 4\nprint(b.x)\ndel b.x\n\n# full use as a decorator\nclass C:\n    def __init__(self, x):\n        self._x = x\n\n    @property\n    def x(self):\n        print(\"x get\")\n        return self._x\n\n    @x.setter\n    def x(self, value):\n        print(\"x set\")\n        self._x = value\n\n    @x.deleter\n    def x(self):\n        print(\"x del\")\n\nc = C(5)\nprint(c.x)\nc.x = 6\nprint(c.x)\ndel c.x\n\n# a property that has no get, set or del\nclass D:\n    prop = property()\nd = D()\ntry:\n    d.prop\nexcept AttributeError:\n    print('AttributeError')\ntry:\n    d.prop = 1\nexcept AttributeError:\n    print('AttributeError')\ntry:\n    del d.prop\nexcept AttributeError:\n    print('AttributeError')\n\n# properties take keyword arguments\nclass E:\n    p = property(lambda self: 42, doc=\"This is truth.\")\n    # not tested for because the other keyword arguments are not accepted\n    # q = property(fget=lambda self: 21, doc=\"Half the truth.\")\nprint(E().p)\n\n# a property as an instance member should not be delegated to\nclass F:\n    def __init__(self):\n        self.prop_member = property()\nprint(type(F().prop_member))\n";
static const char hc_py_73[] = "# test builtin property combined with inheritance\ntry:\n    property\nexcept:\n    print(\"SKIP\")\n    raise SystemExit\n\n# test property in a base class works for derived classes\nclass A:\n    @property\n    def x(self):\n        print('A x')\n        return 123\nclass B(A):\n    pass\nclass C(B):\n    pass\nclass D:\n    pass\nclass E(C, D):\n    pass\nprint(A().x)\nprint(B().x)\nprint(C().x)\nprint(E().x)\n\n# test that we can add a property to base class after creation\nclass F:\n    pass\nF.foo = property(lambda self: print('foo get'))\nclass G(F):\n    pass\nF().foo\nG().foo\n\n# should be able to add a property to already-subclassed class because it already has one\nF.bar = property(lambda self: print('bar get'))\nF().bar\nG().bar\n\n# test case where class (H here) is already subclassed before adding attributes\nclass H:\n    pass\nclass I(H):\n    pass\n\n# should be able to add a normal member to already-subclassed class\nH.val = 2\nprint(I().val)\n\n# should be able to add a property to the derived class\nI.baz = property(lambda self: print('baz get'))\nI().baz\n";
static const char hc_py_74[] = "# test builtin range type\n\n# print\nprint(range(4))\n\n# bool\nprint(bool(range(0)))\nprint(bool(range(10)))\n\n# len\nprint(len(range(0)))\nprint(len(range(4)))\nprint(len(range(1, 4)))\nprint(len(range(1, 4, 2)))\nprint(len(range(1, 4, -1)))\nprint(len(range(4, 1, -1)))\nprint(len(range(4, 1, -2)))\n\n# subscr\nprint(range(4)[0])\nprint(range(4)[1])\nprint(range(4)[-1])\n\n# slice\nprint(range(4)[0:])\nprint(range(4)[1:])\nprint(range(4)[1:2])\nprint(range(4)[1:3])\nprint(range(4)[1::2])\nprint(range(4)[1:-2:2])\nprint(range(1, 4)[:])\nprint(range(1, 4)[0:])\nprint(range(1, 4)[1:])\nprint(range(1, 4)[:-1])\nprint(range(4, 1)[:])\nprint(range(4, 1)[0:])\nprint(range(4, 1)[1:])\nprint(range(4, 1)[:-1])\nprint(range(7, -2, -4)[:])\nprint(range(1, 100, 5)[5:15:3])\nprint(range(1, 100, 5)[15:5:-3])\nprint(range(100, 1, -5)[5:15:3])\nprint(range(100, 1, -5)[15:5:-3])\nprint(range(1, 100, 5)[5:15:-3])\nprint(range(1, 100, 5)[15:5:3])\nprint(range(100, 1, -5)[5:15:-3])\nprint(range(100, 1, -5)[15:5:3])\nprint(range(1, 100, 5)[5:15:3])\nprint(range(1, 100, 5)[15:5:-3])\nprint(range(1, 100, -5)[5:15:3])\nprint(range(1, 100, -5)[15:5:-3])\nprint(range(1, 100, 5)[5:15:-3])\nprint(range(1, 100, 5)[15:5:3])\nprint(range(1, 100, -5)[5:15:-3])\nprint(range(1, 100, -5)[15:5:3])\n\n# for this case MicroPython gives a different stop value but the listed elements are still correct\nprint(list(range(7, -2, -4)[2:-2:]))\n\n# zero step\ntry:\n    range(1, 2, 0)\nexcept ValueError:\n    print(\"ValueError\")\n\n# bad unary op\ntry:\n    -range(1)\nexcept TypeError:\n    print(\"TypeError\")\n\n# bad subscription (can't store)\ntry:\n    range(1)[0] = 1\nexcept TypeError:\n    print(\"TypeError\")\n";
