static const char hc_py_76[] = "# test binary operations on range objects; (in)equality only\n\n# this \"feature test\" actually tests the implementation but is the best we can do\nif range(1) != range(1):\n    print(\"SKIP\")\n    raise SystemExit\n\n# basic (in)equality\nprint(range(1) == range(1))\nprint(range(1) != range(1))\nprint(range(1) != range(2))\n\n# empty range\nprint(range(0) == range(0))\nprint(range(1, 0) == range(0))\nprint(range(1, 4, -1) == range(6, 3))\n\n# 1 element range\nprint(range(1, 4, 10) == range(1, 4, 10))\nprint(range(1, 4, 10) == range(1, 4, 20))\nprint(range(1, 4, 10) == range(1, 8, 20))\n\n# more than 1 element\nprint(range(0, 3, 2) == range(0, 3, 2))\nprint(range(0, 3, 2) == range(0, 4, 2))\nprint(range(0, 3, 2) == range(0, 5, 2))\n\n# unsupported binary op\ntry:\n    range(1) + 10\nexcept TypeError:\n    print('TypeError')\n";
static const char hc_py_77[] = "try:\n    from sys import maxsize\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\n# Test the range builtin at extreme values. (https://github.com/micropython/micropython/issues/17684)\n#\n# This is written using asserts instead of prints because the value of `maxsize` differs.\n#\n# Numbers & counts right up against the max of mp_int_t also cause overflows, such as\n# objrange.c:115:14: runtime error: signed integer overflow: 9223372036854775807 + 1 cannot be represented in type 'long int'\n# so just avoid them for the purposes of this test.\n\nr = range(-maxsize + 1, -1)\nassert r.start == -maxsize + 1\nassert r.stop == -1\nassert r[0] == -maxsize + 1\nassert r[1] == -maxsize + 2\nassert r[-1] == -2\nassert r[-2] == -3\n\nir = iter(r)\nassert next(ir) == -maxsize + 1\nassert next(ir) == -maxsize + 2\n\nr = range(0, maxsize - 1)\nassert len(r) == maxsize - 1\nassert r.stop == maxsize - 1\n\nr = range(maxsize, 0, -1)\nassert len(r) == maxsize\nassert r.start == maxsize\nassert r[0] == maxsize\nassert r[1] == maxsize - 1\nir = iter(r)\nassert next(ir) == maxsize\nassert next(ir) == maxsize - 1\n";
static const char hc_py_78[] = "# test the builtin reverse() function\ntry:\n    reversed\nexcept:\n    print(\"SKIP\")\n    raise SystemExit\n\n# list\nprint(list(reversed([])))\nprint(list(reversed([1])))\nprint(list(reversed([1, 2, 3])))\n\n# tuple\nprint(list(reversed(())))\nprint(list(reversed((1, 2, 3))))\n\n# string\nfor c in reversed('ab'):\n    print(c)\n\n# bytes\nfor b in reversed(b'1234'):\n    print(b)\n\n# range\nfor i in reversed(range(3)):\n    print(i)\n\n# user object\nclass A:\n    def __init__(self):\n        pass\n    def __len__(self):\n        return 3\n    def __getitem__(self, pos):\n        return pos + 1\nfor a in reversed(A()):\n    print(a)\n\n# user object with __reversed__\nclass B:\n    def __reversed__(self):\n        return [1, 2, 3]\nprint(reversed(B()))\n";
