static const char hc_py_83[] = "# test builtin slice\n\n# ensures that slices passed to user types are heap-allocated and can be\n# safely stored as well as not overriden by subsequent slices.\n\n# print slice\nclass A:\n    def __getitem__(self, idx):\n        print(\"get\", idx)\n        print(\"abc\"[1:])\n        print(\"get\", idx)\n        return idx\n\n    def __setitem__(self, idx, value):\n        print(\"set\", idx)\n        print(\"abc\"[1:])\n        print(\"set\", idx)\n        self.saved_idx = idx\n        return idx\n\n    def __delitem__(self, idx):\n        print(\"del\", idx)\n        print(\"abc\"[1:])\n        print(\"del\", idx)\n        return idx\n\n\na = A()\ns = a[1:2:3]\na[4:5:6] = s\ndel a[7:8:9]\n\nprint(a.saved_idx)\n\n# nested slicing\nprint(A()[1 : A()[A()[2:3:4] : 5]])\n\n# tuple slicing\na[1:2, 4:5, 7:8]\na[1, 4:5, 7:8, 2]\na[1:2, a[3:4], 5:6]\n\n# check type\nprint(type(s) is slice)\n";
