static const char hc_py_136[] = "# test for correct binding of self when accessing attr of an instance\n\nclass A:\n    def __init__(self, arg):\n        self.val = arg\n    def __str__(self):\n        return 'A.__str__ ' + str(self.val)\n    def __call__(self, arg):\n        return 'A.__call__', arg\n    def foo(self, arg):\n        return 'A.foo', self.val, arg\n\ndef make_closure(x_in):\n    x = x_in\n    def closure(y):\n        return x, y is c\n    return closure\n\nclass C:\n    # these act like methods and bind self\n\n    def f1(self, arg):\n        return 'C.f1', self is c, arg\n    f2 = lambda self, arg: ('C.f2', self is c, arg)\n    f3 = make_closure('f3') # closure\n    def f4(self, arg): # generator\n        yield self is c, arg\n\n    # these act like simple variables and don't bind self\n\n    f5 = int # builtin type\n    f6 = abs # builtin function\n    f7 = A # user type\n    f8 = A(8) # user instance which is callable\n    f9 = A(9).foo # user bound method\n\nc = C()\nprint(c.f1(1))\nprint(c.f2(2))\nprint(c.f3())\nprint(next(c.f4(4)))\nprint(c.f5(5))\nprint(c.f6(-6))\nprint(c.f7(7))\nprint(c.f8(8))\nprint(c.f9(9))\n\n# test calling the functions accessed via the class itself\nprint(C.f5(10))\nprint(C.f6(-11))\nprint(C.f7(12))\nprint(C.f8(13))\nprint(C.f9(14))\n\n# not working in MicroPython\n#class C(list):\n#    # this acts like a method and binds self\n#    f1 = list.extend\n#c = C()\n#c.f1([3, 1, 2])\n#print(c)\n";
static const char hc_py_137[] = "class foo(object):\n    def __init__(self, value):\n        self.x = value\n\n    def __eq__(self, other):\n        print('eq')\n        return self.x == other.x\n\n    def __lt__(self, other):\n        print('lt')\n        return self.x < other.x\n\n    def __gt__(self, other):\n        print('gt')\n        return self.x > other.x\n\n    def __le__(self, other):\n        print('le')\n        return self.x <= other.x\n\n    def __ge__(self, other):\n        print('ge')\n        return self.x >= other.x\n\nfor i in range(3):\n    for j in range(3):\n        print(foo(i) == foo(j))\n        print(foo(i) < foo(j))\n        print(foo(i) > foo(j))\n        print(foo(i) <= foo(j))\n        print(foo(i) >= foo(j))\n";
static const char hc_py_138[] = "class C1:\n    def __call__(self, val):\n        print('call', val)\n        return 'item'\n\nclass C2:\n\n    def __getattr__(self, k):\n        pass\n\nc1 = C1()\nprint(c1(1))\n\nc2 = C2()\ntry:\n    print(c2(1))\nexcept TypeError:\n    print(\"TypeError\")\n";
static const char hc_py_139[] = "# A contains everything\nclass A:\n    def __contains__(self, key):\n        return True\n\na = A()\nprint(True in a)\nprint(1 in a)\nprint(() in a)\n\n# B contains given things\nclass B:\n    def __init__(self, items):\n        self.items = items\n    def __contains__(self, key):\n        return key in self.items\n\nb = B([])\nprint(1 in b)\nb = B([1, 2])\nprint(1 in b)\nprint(2 in b)\nprint(3 in b)\n\n\nclass C:\n    def __contains__(self, arg):\n        return arg\n\n\nprint(C().__contains__(0))\nprint(C().__contains__(1))\nprint(C().__contains__(''))\nprint(C().__contains__('foo'))\nprint(C().__contains__(None))\n\nprint(0 in C())\nprint(1 in C())\nprint('' in C())\nprint('foo' in C())\nprint(None in C())\n\nprint(0 not in C())\nprint(1 not in C())\nprint('' not in C())\nprint('foo' not in C())\nprint(None not in C())\n";
static const char hc_py_140[] = "# test __delattr__ and __setattr__\n\n# feature test for __setattr__/__delattr__\ntry:\n    class Test():\n        def __delattr__(self, attr): pass\n    del Test().noexist\nexcept AttributeError:\n    print('SKIP')\n    raise SystemExit\n\n# this class just prints the calls to see if they were executed\nclass A():\n    def __getattr__(self, attr):\n        print('get', attr)\n        return 1\n    def __setattr__(self, attr, val):\n        print('set', attr, val)\n    def __delattr__(self, attr):\n        print('del', attr)\na = A()\n\n# check basic behaviour\nprint(getattr(a, 'foo'))\nsetattr(a, 'bar', 2)\ndelattr(a, 'baz')\n\n# check meta behaviour\ngetattr(a, '__getattr__') # should not call A.__getattr__\ngetattr(a, '__setattr__') # should not call A.__getattr__\ngetattr(a, '__delattr__') # should not call A.__getattr__\nsetattr(a, '__setattr__', 1) # should call A.__setattr__\ndelattr(a, '__delattr__') # should call A.__delattr__\n\n# this class acts like a dictionary\nclass B:\n    def __init__(self, d):\n        # store the dict in the class, not instance, so\n        # we don't get infinite recursion in __getattr_\n        B.d = d\n\n    def __getattr__(self, attr):\n        if attr in B.d:\n            return B.d[attr]\n        else:\n            raise AttributeError(attr)\n\n    def __setattr__(self, attr, value):\n        B.d[attr] = value\n\n    def __delattr__(self, attr):\n        del B.d[attr]\n\na = B({\"a\":1, \"b\":2})\nprint(a.a, a.b)\na.a = 3\nprint(a.a, a.b)\ndel a.a\ntry:\n    print(a.a)\nexcept AttributeError:\n    print(\"AttributeError\")\n\n# test object.__setattr__\nclass C:\n    def __init__(self):\n        pass\n\n    def __setattr__(self, attr, value):\n        print(attr, \"=\", value)\n\n    def __delattr__(self, attr):\n        print(\"del\", attr)\n\nc = C()\nc.a = 5\ntry:\n    print(c.a)\nexcept AttributeError:\n    print(\"AttributeError\")\n\nobject.__setattr__(c, \"a\", 5)\nsuper(C, c).__setattr__(\"b\", 6)\nprint(c.a)\nprint(c.b)\n\ntry:\n    # attribute name must be string\n    object.__setattr__(c, 5, 5)\nexcept TypeError:\n    print(\"TypeError\")\n\n\n# test object.__delattr__\ndel c.a\nprint(c.a)\n\nobject.__delattr__(c, \"a\")\ntry:\n    print(c.a)\nexcept AttributeError:\n    print(\"AttributeError\")\n\nsuper(C, c).__delattr__(\"b\")\ntry:\n    print(c.b)\nexcept AttributeError:\n    print(\"AttributeError\")\n\ntry:\n    object.__delattr__(c, \"c\")\nexcept AttributeError:\n    print(\"AttributeError\")\n";
static const char hc_py_141[] = "class Descriptor:\n    def __get__(self, obj, cls):\n        print(\"get\")\n        print(type(obj) is Main)\n        print(cls is Main)\n        return \"result\"\n\n    def __set__(self, obj, val):\n        print(\"set\")\n        print(type(obj) is Main)\n        print(val)\n\n    def __delete__(self, obj):\n        print(\"delete\")\n        print(type(obj) is Main)\n\n    def __set_name__(self, owner, name):\n        print(\"set_name\", name)\n        print(owner.__name__ == \"Main\")\n\n\nclass Main:\n    Forward = Descriptor()\n\n\nm = Main()\ntry:\n    m.__class__\nexcept AttributeError:\n    # Target doesn't support __class__.\n    print(\"SKIP\")\n    raise SystemExit\n\nr = m.Forward\nif \"Descriptor\" in repr(r.__class__):\n    # Target doesn't support descriptors.\n    print(\"SKIP\")\n    raise SystemExit\n\n# Test assignment and deletion.\n\nprint(r)\nm.Forward = \"a\"\ndel m.Forward\n\n# Test that lookup of descriptors like __get__ are not passed into __getattr__.\n\n\nclass NonDescriptor:\n    def __getattr__(self, attr):\n        print(\"getattr\", attr)\n\n\nclass TestClass:\n    non_descriptor = NonDescriptor()\n\n\nprint(isinstance(TestClass().non_descriptor, NonDescriptor))\n\nt = TestClass()\nt.non_descriptor = 123\nprint(t.non_descriptor)\n\ntry:\n    del TestClass().non_descriptor\nexcept AttributeError:\n    print(\"AttributeError\")\n";
static const char hc_py_142[] = "# test __dict__ attribute of a class\n\nif not hasattr(int, \"__dict__\"):\n    print(\"SKIP\")\n    raise SystemExit\n\n\n# dict of a built-in type\nprint(\"from_bytes\" in int.__dict__)\n\n\n# dict of a user class\nclass Foo:\n    a = 1\n    b = \"bar\"\n\n\nd = Foo.__dict__\nprint(d[\"a\"], d[\"b\"])\n\n\n# dict of a class that has no locals_dict (return empty dict).\nd = type(type('')).__dict__\nprint(d is not None)\n";
