static const char hc_py_144[] = "# test that __getattr__ and instance members don't override builtins\nclass C:\n    def __init__(self):\n        self.__add__ = lambda: print('member __add__')\n    def __add__(self, x):\n        print('__add__')\n    def __getattr__(self, attr):\n        print('__getattr__', attr)\n        return None\n\nc = C()\nc.add # should call __getattr__\nc.__add__() # should load __add__ instance directly\nc + 1 # should call __add__ method directly\n";
static const char hc_py_145[] = "class A:\n    def __init__(self, x):\n        print('A init', x)\n        self.x = x\n\n    def f(self):\n        print(self.x, self.y)\n\nclass B(A):\n    def __init__(self, x, y):\n        A.__init__(self, x)\n        print('B init', x, y)\n        self.y = y\n\n    def g(self):\n        print(self.x, self.y)\n\nA(1)\nb = B(1, 2)\nb.f()\nb.g()\n";
static const char hc_py_146[] = "# test multiple inheritance of user classes\n\nclass A:\n    def __init__(self, x):\n        print('A init', x)\n        self.x = x\n\n    def f(self):\n        print(self.x)\n\n    def f2(self):\n        print(self.x)\n\nclass B:\n    def __init__(self, x):\n        print('B init', x)\n        self.x = x\n\n    def f(self):\n        print(self.x)\n\n    def f3(self):\n        print(self.x)\n\n\nclass Sub(A, B):\n    def __init__(self):\n        A.__init__(self, 1)\n        B.__init__(self, 2)\n        print('Sub init')\n\n    def g(self):\n        print(self.x)\n\nprint(issubclass(Sub, A))\nprint(issubclass(Sub, B))\n\no = Sub()\nprint(o.x)\no.f()\no.f2()\no.f3()\n";
static const char hc_py_147[] = "# Case 1: Immutable object (e.g. number-like)\n# __iadd__ should not be defined, will be emulated using __add__\n\nclass A:\n\n    def __init__(self, v):\n        self.v = v\n\n    def __add__(self, o):\n        return A(self.v + o.v)\n\n    def __repr__(self):\n        return \"A({})\".format(self.v)\n\na = A(5)\nb = a\na += A(3)\nprint(a)\n# Should be original a's value, i.e. A(5)\nprint(b)\n\n# Case 2: Mutable object (e.g. list-like)\n# __iadd__ should be defined\n\nclass L:\n\n    def __init__(self, v):\n        self.v = v\n\n    def __add__(self, o):\n        # Should not be caled in this test\n        print(\"L.__add__\")\n        return L(self.v + o.v)\n\n    def __iadd__(self, o):\n        self.v += o.v\n        return self\n\n    def __repr__(self):\n        return \"L({})\".format(self.v)\n\nc = L([1, 2])\nd = c\nc += L([3, 4])\nprint(c)\n# Should be updated c's value, i.e. L([1, 2, 3, 4])\nprint(d)\n";
static const char hc_py_148[] = "# Test inplace special methods enabled by MICROPY_PY_ALL_INPLACE_SPECIAL_METHODS\n\n\nclass A:\n    def __imul__(self, other):\n        print(\"__imul__\")\n        return self\n\n    def __imatmul__(self, other):\n        print(\"__imatmul__\")\n        return self\n\n    def __ifloordiv__(self, other):\n        print(\"__ifloordiv__\")\n        return self\n\n    def __itruediv__(self, other):\n        print(\"__itruediv__\")\n        return self\n\n    def __imod__(self, other):\n        print(\"__imod__\")\n        return self\n\n    def __ipow__(self, other):\n        print(\"__ipow__\")\n        return self\n\n    def __ior__(self, other):\n        print(\"__ior__\")\n        return self\n\n    def __ixor__(self, other):\n        print(\"__ixor__\")\n        return self\n\n    def __iand__(self, other):\n        print(\"__iand__\")\n        return self\n\n    def __ilshift__(self, other):\n        print(\"__ilshift__\")\n        return self\n\n    def __irshift__(self, other):\n        print(\"__irshift__\")\n        return self\n\n\na = A()\n\ntry:\n    a *= None\nexcept TypeError:\n    print(\"SKIP\")\n    raise SystemExit\n\na @= None\na //= None\na /= None\na %= None\na **= None\na |= None\na ^= None\na &= None\na <<= None\na >>= None\n\n# Normal operator should not fallback to inplace operator\ntry:\n    a * None\nexcept TypeError:\n    print(\"TypeError\")\n";
