static const char hc_py_150[] = "# test class with __getitem__, __setitem__, __delitem__ methods\n\nclass C:\n    def __getitem__(self, item):\n        print('get', item)\n        return 'item'\n\n    def __setitem__(self, item, value):\n        print('set', item, value)\n\n    def __delitem__(self, item):\n        print('del', item)\n\nc = C()\nprint(c[1])\nc[1] = 2\ndel c[3]\n\n# index not supported\nclass A:\n    pass\na = A()\ntry:\n    a[1]\nexcept TypeError:\n    print('TypeError')\n";
