static const char hc_py_152[] = "try:\n    # If we don't expose object.__new__ (small ports), there's\n    # nothing to test.\n    object.__new__\nexcept AttributeError:\n    print(\"SKIP\")\n    raise SystemExit\n\nclass A:\n    def __new__(cls):\n        print(\"A.__new__\")\n        return super(cls, A).__new__(cls)\n\n    def __init__(self):\n        print(\"A.__init__\")\n\n    def meth(self):\n        print('A.meth')\n\n#print(A.__new__)\n#print(A.__init__)\n\na = A()\na.meth()\n\na = A.__new__(A)\na.meth()\n\n#print(a.meth)\n#print(a.__init__)\n#print(a.__new__)\n\n# __new__ should automatically be a staticmethod, so this should work\na = a.__new__(A)\na.meth()\n\n# __new__ returns not an instance of the class (None here), __init__\n# should not be called\n\nclass B:\n    def __new__(self, v1, v2):\n        print(\"B.__new__\", v1, v2)\n\n    def __init__(self, v1, v2):\n        # Should not be called in this test\n        print(\"B.__init__\", v1, v2)\n\nprint(\"B inst:\", B(1, 2))\n\n\n# Variation of the above, __new__ returns an instance of another class,\n# __init__ should not be called\n\nclass Dummy: pass\n\nclass C:\n    def __new__(cls):\n        print(\"C.__new__\")\n        return Dummy()\n\n    def __init__(self):\n        # Should not be called in this test\n        print(\"C.__init__\")\n\nc = C()\nprint(isinstance(c, Dummy))\n";
static const char hc_py_153[] = "# Test that returning of NotImplemented from binary op methods leads to\n# TypeError.\ntry:\n    NotImplemented\nexcept NameError:\n    print(\"SKIP\")\n    raise SystemExit\n\nclass C:\n    def __init__(self, value):\n        self.value = value\n\n    def __str__(self):\n        return \"C({})\".format(self.value)\n\n    def __add__(self, rhs):\n        print(self, '+', rhs)\n        return NotImplemented\n\n    def __sub__(self, rhs):\n        print(self, '-', rhs)\n        return NotImplemented\n\n    def __lt__(self, rhs):\n        print(self, '<', rhs)\n        return NotImplemented\n\n    def __neg__(self):\n        print('-', self)\n        return NotImplemented\n\nc = C(0)\n\ntry:\n    c + 1\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    c - 2\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    c < 1\nexcept TypeError:\n    print(\"TypeError\")\n\n# NotImplemented isn't handled specially in unary methods\nprint(-c)\n\n# Test that NotImplemented can be hashed\nprint(type(hash(NotImplemented)))\n";
