static const char hc_py_155[] = "# test using an OrderedDict as the locals to construct a class\n\ntry:\n    from collections import OrderedDict\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\nif not hasattr(int, \"__dict__\"):\n    print(\"SKIP\")\n    raise SystemExit\n\n\nA = type(\"A\", (), OrderedDict(a=1, b=2, c=3, d=4, e=5))\nprint([k for k in A.__dict__.keys() if not k.startswith(\"_\")])\n";
static const char hc_py_156[] = "# Test reverse operators.\n\n# Test user type with integers.\nclass A:\n    def __init__(self, v):\n        self.v = v\n\n    def __add__(self, o):\n        if isinstance(o, A):\n            return A(self.v + o.v)\n        return A(self.v + o)\n\n    def __radd__(self, o):\n        return A(self.v + o)\n\n    def __repr__(self):\n        return \"A({})\".format(self.v)\n\n\nprint(A(3) + 1)\nprint(2 + A(5))\n\n\n# Test user type with strings.\nclass B:\n    def __init__(self, v):\n        self.v = v\n\n    def __repr__(self):\n        return \"B({})\".format(self.v)\n\n    def __ror__(self, o):\n        return B(o + \"|\" + self.v)\n\n    def __radd__(self, o):\n        return B(o + \"+\" + self.v)\n\n    def __rmul__(self, o):\n        return B(o + \"*\" + self.v)\n\n    def __rtruediv__(self, o):\n        return B(o + \"/\" + self.v)\n\n\nprint(\"a\" | B(\"b\"))\nprint(\"a\" + B(\"b\"))\nprint(\"a\" * B(\"b\"))\nprint(\"a\" / B(\"b\"))\n\nx = \"a\"; x |= B(\"b\"); print(x)\nx = \"a\"; x += B(\"b\"); print(x)\nx = \"a\"; x *= B(\"b\"); print(x)\nx = \"a\"; x /= B(\"b\"); print(x)\n";
static const char hc_py_157[] = "# Test that __set_name__ can access and mutate its owner argument.\n\n\ndef skip_if_no_descriptors():\n    class Descriptor:\n        def __get__(self, obj, cls):\n            return\n\n    class TestClass:\n        Forward = Descriptor()\n\n    a = TestClass()\n    try:\n        a.__class__\n    except AttributeError:\n        # Target doesn't support __class__.\n        print(\"SKIP\")\n        raise SystemExit\n\n    b = a.Forward\n    if \"Descriptor\" in repr(b.__class__):\n        # Target doesn't support descriptors.\n        print(\"SKIP\")\n        raise SystemExit\n\n\nskip_if_no_descriptors()\n\n\n# Test basic accesses and mutations.\n\n\nclass GetSibling:\n    def __set_name__(self, owner, name):\n        print(getattr(owner, name + \"_sib\"))\n\n\nclass GetSiblingTest:\n    desc = GetSibling()\n    desc_sib = 111\n\n\nt110 = GetSiblingTest()\n\n\nclass SetSibling:\n    def __set_name__(self, owner, name):\n        setattr(owner, name + \"_sib\", 121)\n\n\nclass SetSiblingTest:\n    desc = SetSibling()\n\n\nt120 = SetSiblingTest()\n\nprint(t120.desc_sib)\n\n\nclass DelSibling:\n    def __set_name__(self, owner, name):\n        delattr(owner, name + \"_sib\")\n\n\nclass DelSiblingTest:\n    desc = DelSibling()\n    desc_sib = 131\n\n\nt130 = DelSiblingTest()\n\ntry:\n    print(t130.desc_sib)\nexcept AttributeError:\n    print(\"AttributeError\")\n\n\nclass GetSelf:\n    x = 211\n\n    def __set_name__(self, owner, name):\n        print(getattr(owner, name).x)\n\n\nclass GetSelfTest:\n    desc = GetSelf()\n\n\nt210 = GetSelfTest()\n\n\nclass SetSelf:\n    def __set_name__(self, owner, name):\n        setattr(owner, name, 221)\n\n\nclass SetSelfTest:\n    desc = SetSelf()\n\n\nt220 = SetSelfTest()\n\nprint(t220.desc)\n\n\nclass DelSelf:\n    def __set_name__(self, owner, name):\n        delattr(owner, name)\n\n\nclass DelSelfTest:\n    desc = DelSelf()\n\n\nt230 = DelSelfTest()\n\ntry:\n    print(t230.desc)\nexcept AttributeError:\n    print(\"AttributeError\")\n\n\n# Test exception behavior.\n\n\nclass Raise:\n    def __set_name__(self, owner, name):\n        raise Exception()\n\n\ntry:\n\n    class RaiseTest:\n        desc = Raise()\nexcept Exception as e:  # CPython raises RuntimeError, MicroPython propagates the original exception\n    print(\"Exception\")\n\n\n# Ensure removed/overwritten class members still get __set_name__ called.\n\n\nclass SetSpecific:\n    def __init__(self, sib_name, sib_replace):\n        self.sib_name = sib_name\n        self.sib_replace = sib_replace\n\n    def __set_name__(self, owner, name):\n        setattr(owner, self.sib_name, self.sib_replace)\n\n\nclass SetReplaceTest:\n    a = SetSpecific(\"b\", 312)  # one of these is changed first\n    b = SetSpecific(\"a\", 311)\n\n\nt310 = SetReplaceTest()\nprint(t310.a)\nprint(t310.b)\n\n\nclass DelSpecific:\n    def __init__(self, sib_name):\n        self.sib_name = sib_name\n\n    def __set_name__(self, owner, name):\n        delattr(owner, self.sib_name)\n\n\nclass DelReplaceTest:\n    a = DelSpecific(\"b\")  # one of these is removed first\n    b = DelSpecific(\"a\")\n\n\nt320 = DelReplaceTest()\ntry:\n    print(t320.a)\nexcept AttributeError:\n    print(\"AttributeError\")\ntry:\n    print(t320.b)\nexcept AttributeError:\n    print(\"AttributeError\")\n";
static const char hc_py_158[] = "# Test to make sure there's no sequence hazard even when a __set_name__ implementation\n# mutates and reorders the namespace of its owner class.\n# VERY hard bug to prove out except via a stochastic test.\n\n\ntry:\n    from random import choice\n    import re\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\n\ndef skip_if_no_descriptors():\n    class Descriptor:\n        def __get__(self, obj, cls):\n            return\n\n    class TestClass:\n        Forward = Descriptor()\n\n    a = TestClass()\n    try:\n        a.__class__\n    except AttributeError:\n        # Target doesn't support __class__.\n        print(\"SKIP\")\n        raise SystemExit\n\n    b = a.Forward\n    if \"Descriptor\" in repr(b.__class__):\n        # Target doesn't support descriptors.\n        print(\"SKIP\")\n        raise SystemExit\n\n\nskip_if_no_descriptors()\n\nletters = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n\n# Would be r\"[A-Z]{5}\", but not all ports support the {n} quantifier.\njunk_re = re.compile(r\"[A-Z][A-Z][A-Z][A-Z][A-Z]\")\n\n\ndef junk_fill(obj, n=10):  # Add randomly-generated attributes to an object.\n    for i in range(n):\n        name = \"\".join(choice(letters) for j in range(5))\n        setattr(obj, name, object())\n\n\ndef junk_clear(obj):  # Remove attributes added by junk_fill.\n    to_del = [name for name in dir(obj) if junk_re.match(name)]\n    for name in to_del:\n        delattr(obj, name)\n\n\ndef junk_sequencer():\n    global runs\n    try:\n        while True:\n            owner, name = yield\n            runs[name] = runs.get(name, 0) + 1\n            junk_fill(owner)\n    finally:\n        junk_clear(owner)\n\n\nclass JunkMaker:\n    def __set_name__(self, owner, name):\n        global seq\n        seq.send((owner, name))\n\n\nruns = {}\nseq = junk_sequencer()\nnext(seq)\n\n\nclass Main:\n    a = JunkMaker()\n    b = JunkMaker()\n    c = JunkMaker()\n    d = JunkMaker()\n    e = JunkMaker()\n    f = JunkMaker()\n    g = JunkMaker()\n    h = JunkMaker()\n    i = JunkMaker()\n    j = JunkMaker()\n    k = JunkMaker()\n    l = JunkMaker()\n    m = JunkMaker()\n    n = JunkMaker()\n    o = JunkMaker()\n    p = JunkMaker()\n    q = JunkMaker()\n    r = JunkMaker()\n    s = JunkMaker()\n    t = JunkMaker()\n    u = JunkMaker()\n    v = JunkMaker()\n    w = JunkMaker()\n    x = JunkMaker()\n    y = JunkMaker()\n    z = JunkMaker()\n\n\nseq.close()\n\nfor k in letters.lower():\n    print(k, runs.get(k, 0))\n";
