static const char hc_py_186[] = "try:\n    from collections import deque\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\n# Initial sequence is supported\nd = deque([1, 2, 3], 10)\n\n# iteration over sequence\nfor x in d:\n    print(x)\n\n# Iterables larger than maxlen have the beginnings removed, also tests\n# iteration through conversion to list\nd = deque([1, 2, 3, 4, 5], 3)\nprint(list(d))\n\n# Empty iterables are also supported\ndeque([], 10)\n\n# Extending deques with iterables\nd.extend([6, 7])\nprint(list(d))\n\n# Accessing queue elements via index\nd = deque((0, 1, 2, 3), 5)\nprint(d[0], d[1], d[-1])\n\n# Writing queue elements via index\nd[3] = 5\nprint(d[3])\n\n# Access the last element via index, when the last element is at various locations\nd = deque((), 2)\nfor i in range(4):\n    d.append(i)\n    print(i, d[-1])\n\n# Write the last element then access all elements from the end\nd[-1] = 4\nprint(d[-2], d[-1])\n\n# Accessing indices out of bounds raises IndexError\ntry:\n    d[4]\nexcept IndexError:\n    print(\"IndexError\")\n\ntry:\n    d[4] = 0\nexcept IndexError:\n    print(\"IndexError\")\n";
static const char hc_py_187[] = "# Test MicroPython-specific features of collections.deque.\n\ntry:\n    from collections import deque\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\n\n# Only fixed-size deques are supported, so length arg is mandatory.\ntry:\n    deque(())\nexcept TypeError:\n    print(\"TypeError\")\n\n# Test third argument: flags when True means check for under/overflow\nd = deque((), 2, True)\n\ntry:\n    d.popleft()\nexcept IndexError:\n    print(\"IndexError\")\n\ntry:\n    d.pop()\nexcept IndexError:\n    print(\"IndexError\")\n\n# Removing elements with del is not supported, fallback to\n# mp_obj_subscr() error message.\ntry:\n    del d[0]\nexcept TypeError:\n    print(\"TypeError\")\n\nprint(d.append(1))\nprint(d.popleft())\n\nd.append(2)\nprint(d.popleft())\n\nd.append(3)\nd.append(4)\nprint(d.popleft(), d.popleft())\ntry:\n    d.popleft()\nexcept IndexError as e:\n    print(repr(e))\n\ntry:\n    d.pop()\nexcept IndexError as e:\n    print(repr(e))\n\nd.append(5)\nd.append(6)\nprint(len(d))\ntry:\n    d.append(7)\nexcept IndexError as e:\n    print(repr(e))\n\ntry:\n    d.appendleft(8)\nexcept IndexError as e:\n    print(repr(e))\n\nprint(len(d))\n\nprint(d.popleft(), d.popleft())\nprint(len(d))\ntry:\n    d.popleft()\nexcept IndexError as e:\n    print(repr(e))\n";
