static const char hc_py_195[] = "# test that fixed dictionaries cannot be modified\n\ntry:\n    import errno\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\n# Save a copy of errno.errorcode, so we can check later\n# that it hasn't been modified.\nerrorcode_copy = errno.errorcode.copy()\n\ntry:\n    errno.errorcode.popitem()\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    errno.errorcode.pop(0)\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    errno.errorcode.setdefault(0, 0)\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    errno.errorcode.update([(1, 2)])\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    del errno.errorcode[1]\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    errno.errorcode[1] = 'foo'\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    errno.errorcode.clear()\nexcept TypeError:\n    print(\"TypeError\")\n\nassert errno.errorcode == errorcode_copy\n";
