static const char hc_py_224[] = "# test for+range, mostly to check optimisation of this pair\n\n# apply args using *\nfor x in range(*(1, 3)):\n    print(x)\nfor x in range(1, *(6, 2)):\n    print(x)\n\n# zero step\ntry:\n    for x in range(1, 2, 0):\n        pass\nexcept ValueError:\n    print('ValueError')\n\n# apply args using **\ntry:\n    for x in range(**{'end':1}):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(0, **{'end':1}):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(0, 1, **{'step':1}):\n        print(x)\nexcept TypeError:\n    print('TypeError')\n\n# keyword args\ntry:\n    for x in range(end=1):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(0, end=1):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(start=0, end=1):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(0, 1, step=1):\n        print(x)\nexcept TypeError:\n    print('TypeError')\n\n# argument is a comprehension\ntry:\n    for x in range(0 for i in []):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(0, (0 for i in [])):\n        print(x)\nexcept TypeError:\n    print('TypeError')\ntry:\n    for x in range(0, 1, (0 for i in [])):\n        print(x)\nexcept TypeError:\n    print('TypeError')\n";
