static const char hc_py_261[] = "def gen():\n    yield 1\n    yield 2\n    yield 3\n    yield 4\n\ndef gen2():\n    yield -1\n    print((yield from gen()))\n    yield 10\n    yield 11\n\ng = gen2()\nprint(next(g))\nprint(next(g))\ng.close()\ntry:\n    print(next(g))\nexcept StopIteration:\n    print(\"StopIteration\")\n\n\n# Now variation of same test, but with leaf generator\n# swallowing GeneratorExit exception - its upstream gen\n# generator should still receive one.\ndef gen3():\n    yield 1\n    try:\n        yield 2\n    except GeneratorExit:\n        print(\"leaf caught GeneratorExit and swallowed it\")\n        return\n    yield 3\n    yield 4\n\ndef gen4():\n    yield -1\n    try:\n        print((yield from gen3()))\n    except GeneratorExit:\n        print(\"delegating caught GeneratorExit\")\n        raise\n    yield 10\n    yield 11\n\ng = gen4()\nprint(next(g))\nprint(next(g))\nprint(next(g))\ng.close()\ntry:\n    print(next(g))\nexcept StopIteration:\n    print(\"StopIteration\")\n\n\n# Yet another variation - leaf generator gets GeneratorExit,\n# and reraises a new GeneratorExit. This still should close chain properly.\ndef gen5():\n    yield 1\n    try:\n        yield 2\n    except GeneratorExit:\n        print(\"leaf caught GeneratorExit and reraised GeneratorExit\")\n        raise GeneratorExit(123)\n    yield 3\n    yield 4\n\ndef gen6():\n    yield -1\n    try:\n        print((yield from gen5()))\n    except GeneratorExit:\n        print(\"delegating caught GeneratorExit\")\n        raise\n    yield 10\n    yield 11\n\ng = gen6()\nprint(next(g))\nprint(next(g))\nprint(next(g))\ng.close()\ntry:\n    print(next(g))\nexcept StopIteration:\n    print(\"StopIteration\")\n\n# case where generator ignores the close request and yields instead\ndef gen7():\n    try:\n        yield 123\n    except GeneratorExit:\n        yield 456\n\ng = gen7()\nprint(next(g))\ntry:\n    g.close()\nexcept RuntimeError:\n    print('RuntimeError')\n\n# case where close is propagated up to a built-in iterator\ndef gen8():\n    g = range(2)\n    yield from g\ng = gen8()\nprint(next(g))\ng.close()\n\n# case with a user-defined close method\nclass Iter:\n    def __iter__(self):\n        return self\n    def __next__(self):\n        return 1\n    def close(self):\n        print('close')\ndef gen9():\n    yield from Iter()\ng = gen9()\nprint(next(g))\ng.close()\n";
