static const char hc_py_277[] = "def gen1():\n    yield 1\n    yield 2\n\n# Test that it's possible to close just created gen\ng = gen1()\nprint(g.close())\ntry:\n    next(g)\nexcept StopIteration:\n    print(\"StopIteration\")\n\n# Test that it's possible to close gen in progress\ng = gen1()\nprint(next(g))\nprint(g.close())\ntry:\n    next(g)\n    print(\"No StopIteration\")\nexcept StopIteration:\n    print(\"StopIteration\")\n\n# Test that it's possible to close finished gen\ng = gen1()\nprint(list(g))\nprint(g.close())\ntry:\n    next(g)\n    print(\"No StopIteration\")\nexcept StopIteration:\n    print(\"StopIteration\")\n\n\n# Throwing GeneratorExit in response to close() is ok\ndef gen2():\n    try:\n        yield 1\n        yield 2\n    except:\n        print('raising GeneratorExit')\n        raise GeneratorExit\n\ng = gen2()\nnext(g)\nprint(g.close())\n\n# Any other exception is propagated to the .close() caller\ndef gen3():\n    try:\n        yield 1\n        yield 2\n    except:\n        raise ValueError\n\ng = gen3()\nnext(g)\ntry:\n    print(g.close())\nexcept ValueError:\n    print(\"ValueError\")\n";
static const char hc_py_278[] = "# a generator that closes over outer variables\ndef f():\n    x = 1 # closed over by g\n    def g():\n        yield x\n        yield x + 1\n    return g()\nfor i in f():\n    print(i)\n\n# a generator that has its variables closed over\ndef f():\n    x = 1 # closed over by g\n    def g():\n        return x + 1\n    yield g()\n    x = 2\n    yield g()\nfor i in f():\n    print(i)\n\n# using comprehensions, the inner generator closes over y\ngenerator_of_generators = (((x, y) for x in range(2)) for y in range(3))\nfor i in generator_of_generators:\n    for j in i:\n        print(j)\n\n# test that printing of closed-over generators doesn't lead to segfaults\ndef genc():\n    foo = 1\n    repr(lambda: (yield foo))\ngenc()\n";
static const char hc_py_279[] = "# Test proper handling of exceptions within generator across yield\ndef gen():\n    try:\n        yield 1\n        raise ValueError\n    except ValueError:\n        print(\"Caught\")\n    yield 2\n\nfor i in gen():\n    print(i)\n\n\n# Test throwing exceptions out of generator\ndef gen2():\n    yield 1\n    raise ValueError\n    yield 2\n    yield 3\n\ng = gen2()\nprint(next(g))\ntry:\n    print(next(g))\nexcept ValueError:\n    print(\"ValueError\")\n\ntry:\n    print(next(g))\nexcept StopIteration:\n    print(\"StopIteration\")\n\n\n# Test throwing exception into generator\ndef gen3():\n    yield 1\n    try:\n        yield 2\n    except ValueError:\n        print(\"ValueError received\")\n        yield 3\n    yield 4\n    yield 5\n\ng = gen3()\nprint(next(g))\nprint(next(g))\nprint(\"out of throw:\", g.throw(ValueError))\nprint(next(g))\ntry:\n    print(\"out of throw2:\", g.throw(ValueError))\nexcept ValueError:\n    print(\"Boomerang ValueError caught\")\n";
