static const char hc_py_287[] = "# Tests that the correct nested exception handler is used when\n# throwing into a generator (previously failed on native emitter).\n\ndef gen():\n    try:\n        yield 1\n        try:\n            yield 2\n            try:\n                yield 3\n            except Exception:\n                yield 4\n                print(0)\n            yield 5\n        except Exception:\n            yield 6\n            print(1)\n        yield 7\n    except Exception:\n        yield 8\n        print(2)\n    yield 9\n\nfor i in range(1, 10):\n    g = gen()\n    try:\n        for _ in range(i):\n            print(next(g))\n        print(g.throw(ValueError))\n    except ValueError:\n        print('ValueError')\n    except StopIteration:\n        print('StopIteration')\n";
