static const char hc_py_292[] = "# test if conditions which are optimised by the compiler\n\nif 0:\n    print(5)\nelse:\n    print(6)\n\nif 1:\n    print(7)\n\nif 2:\n    print(8)\n\nif -1:\n    print(9)\nelif 1:\n    print(10)\n\nif 0:\n    print(11)\nelse:\n    print(12)\n\nif 0:\n    print(13)\nelif 1:\n    print(14)\n\nif 0:\n    print(15)\nelif 0:\n    print(16)\nelse:\n    print(17)\n\nif not False:\n    print('a')\n\nif not True:\n    print('a')\nelse:\n    print('b')\n\nif False:\n    print('a')\nelse:\n    print('b')\n\nif True:\n    print('a')\n\nif (1,):\n    print('a')\n\nif not (1,):\n    print('a')\nelse:\n    print('b')\n\n# test evaluation of the if-condition with tuples as arguments\n# non-constant tuples should be evaluated even though they will evaluate to true\n\ndef f(x):\n    print(\"f\", x)\n\nif (f(1),):\n    print(18)\n\nif (f(2), f(3)):\n    print(19)\n\n# test if-conditions within a function\n\nf2 = 0\n\ndef f(t1, t2, f1):\n    if False:\n        print(1)\n    if True:\n        print(1)\n    if ():\n        print(1)\n    if (1,):\n        print(1)\n    if (1, 2):\n        print(1)\n    if t1 and t2:\n        print(1)\n    if (t1 and t2): # parsed differently to above\n        print(1)\n    if not (t1 and f1):\n        print(1)\n    if t1 or t2:\n        print(1)\n    if (t1 or t2): # parse differently to above\n        print(1)\n    if f1 or t1:\n        print(1)\n    if not (f1 or f2):\n        print(1)\n    if t1 and f1 or t1 and t2:\n        print(1)\n    if (f1 or t1) and (f2 or t2):\n        print(1)\n\nf(True, 1, False)\n";
