static const char hc_py_294[] = "# Test importing a method from a class instance.\n# This is not a common thing to do, but ensures MicroPython has the same semantics as CPython.\n\nimport sys\n\nif not hasattr(sys, \"modules\"):\n    print(\"SKIP\")\n    raise SystemExit\n\n\nclass A:\n    def __init__(self, value):\n        self.value = value\n\n    def meth(self):\n        return self.value\n\n    def meth_with_arg(self, a):\n        return [self.value, a]\n\n\n# Register a class instance as the module \"mod\".\nsys.modules[\"mod\"] = A(1)\n\n# Try importing it as a module.\nimport mod\n\nprint(mod.meth())\nprint(mod.meth_with_arg(2))\n\n# Change the module.\nsys.modules[\"mod\"] = A(3)\n\n# Try importing it using \"from ... import\".\nfrom mod import meth, meth_with_arg\n\nprint(meth())\nprint(meth_with_arg(4))\n";
static const char hc_py_295[] = "# Test \"from x import *\" where x is something other than a module.\n\nimport sys\n\ntry:\n    next(iter([]), 42)\nexcept TypeError:\n    # Two-argument version of next() not supported.  We are probably not at\n    # MICROPY_CONFIG_ROM_LEVEL_BASIC_FEATURES which is needed for \"import *\".\n    print(\"SKIP\")\n    raise SystemExit\n\nprint(\"== test with a class as a module ==\")\n\n\nclass M:\n    x = \"a1\"\n\n    def __init__(self):\n        self.x = \"a2\"\n\n\nsys.modules[\"mod\"] = M\nfrom mod import *\n\nprint(x)\n\nsys.modules[\"mod\"] = M()\nfrom mod import *\n\nprint(x)\n\nprint(\"== test with a class as a module that overrides __all__ ==\")\n\n\nclass M:\n    __all__ = (\"y\",)\n    x = \"b1\"\n    y = \"b2\"\n\n    def __init__(self):\n        self.__all__ = (\"x\",)\n        self.x = \"b3\"\n        self.y = \"b4\"\n\n\nsys.modules[\"mod\"] = M\nx = None\nfrom mod import *\n\nprint(x, y)\n\nsys.modules[\"mod\"] = M()\nfrom mod import *\n\nprint(x, y)\n\nprint(\"== test with objects that don't have a __dict__ ==\")\n\nsys.modules[\"mod\"] = 1\ntry:\n    from mod import *\n    # MicroPython raises AttributeError, CPython raises ImportError.\nexcept (AttributeError, ImportError):\n    print(\"ImportError\")\n";
