static const char hc_py_298[] = "# test support for 64-bit long integers\n# (some ports don't support arbitrary precision but do support these)\n\n# this test is adapted from int_big1.py with numbers kept within 64-bit signed range\n\n# to test arbitrary precision integers\n\nx = 1000000000000000000\nxn = -1000000000000000000\ny = 2000000000000000000\n\n# printing\nprint(x)\nprint(y)\nprint('%#X' % (x - x)) # print prefix\nprint('{:#,}'.format(x)) # print with commas\n\n# construction\nprint(int(x))\n\n# addition\nprint(x + 1)\nprint(x + y)\nprint(x + xn == 0)\nprint(bool(x + xn))\n\n# subtraction\nprint(x - 1)\nprint(x - y)\nprint(y - x)\nprint(x - x == 0)\nprint(bool(x - x))\n\n# multiplication\nprint(x * 2)\nprint(1090511627776 * 1048500)\n\n# integer division\nprint(x // 2)\nprint(y // x)\n\n# bit inversion\nprint(~x)\nprint(~(-x))\n\n# left shift\nprint(\"left shift positive\")\nx = 0x40000000\nfor i in range(32):\n    x = x << 1\n    print(x)\n\n# right shift\nprint(\"right shift positive\")\nx = 0x2000000000000000  # TODO: why can't second-tip bit be set?\nfor i in range(64):\n    x = x >> 1\n    print(x)\n\n# left shift of a negative number\nprint(\"left shift negative\")\nfor i in range(8):\n    print(-10000000000000000 << i)\n    print(-10000000000000001 << i)\n    print(-10000000000000002 << i)\n    print(-10000000000000003 << i)\n    print(-10000000000000004 << i)\n\n\n# right shift of a negative number\nprint(\"right shift negative\")\nfor i in range(8):\n    print(-1000000000000000000 >> i)\n    print(-1000000000000000001 >> i)\n    print(-1000000000000000002 >> i)\n    print(-1000000000000000003 >> i)\n    print(-1000000000000000004 >> i)\n\n# conversion from string\nprint(int(\"1234567890123456789\"))\nprint(int(\"-1234567890123456789\"))\nprint(int(\"1234567890abcdef\", 16))\nprint(int(\"1234567890ABCDEF\", 16))\nprint(int(\"-1234567890ABCDEF\", 16))\nprint(int(\"ijklmnopqrsz\", 36))\n\n# numbers close to 64-bit limits\nprint(int(\"-9111222333444555666\"))\nprint(int(\"9111222333444555666\"))\n\n# numbers with preceding 0s\nprint(int(\"-00000000000000000000009111222333444555666\"))\nprint(int(\"0000000000000000000000009111222333444555666\"))\n\n# invalid characters in string\ntry:\n    print(int(\"1234567890abcdef\"))\nexcept ValueError:\n    print('ValueError');\ntry:\n    print(int(\"123456789\\x01\"))\nexcept ValueError:\n    print('ValueError');\n\n# test parsing ints just on threshold of small to big\n# for 32 bit archs\nx = 1073741823 # small\nx = -1073741823 # small\nx = 1073741824 # big\nx = -1073741824 # big\n# for 64 bit archs\nx = 4611686018427387903 # small\nx = -4611686018427387903 # small\nx = 4611686018427387904 # big\nx = -4611686018427387904 # big\n\n# sys.maxsize is a constant bigint, so test it's compatible with dynamic ones\nimport sys\nif hasattr(sys, \"maxsize\"):\n    print(sys.maxsize - 1 + 1 == sys.maxsize)\nelse:\n    print(True)  # No maxsize property in this config\n\n# test extraction of big int value via mp_obj_get_int_maybe\nx = 1 << 62\nprint('a' * (x + 4 - x))\n\n# test overflow check in mp_obj_get_int_maybe\nx = 1 << 32\nr = None\ntry:\n    r = range(0, x)\nexcept OverflowError:\n    # 32-bit target, correctly handled the overflow of x\n    print(\"ok\")\nif r is not None:\n    if len(r) == x:\n        # 64-bit target, everything is just a small-int\n        print(\"ok\")\n    else:\n        # 32-bit target that did not handle the overflow of x\n        print(\"unhandled overflow\")\n\n# negative shifts are invalid\ntry:\n    print((1 << 48) >> -4)\nexcept ValueError as e:\n    print(e)\n\ntry:\n    print((1 << 48) << -6)\nexcept ValueError as e:\n    print(e)\n\n# Test that the most extreme 64 bit integer values all parse with int()\nprint(int(\"-9223372036854775807\"))\nprint(int(\"-9223372036854775808\"))\nprint(int(\"9223372036854775807\"))\n\n# Test that the most negative 64 bit integer can be formed via arithmetic\nprint(-9223372036854775807-1)\n";
static const char hc_py_299[] = "# to test arbitrary precision integers\n\nx = 1000000000000000000000000000000\nxn = -1000000000000000000000000000000\ny = 2000000000000000000000000000000\n\n# printing\nprint(x)\nprint(y)\nprint('%#X' % (x - x)) # print prefix\nprint('{:#,}'.format(x)) # print with commas\n\n# construction\nprint(int(x))\n\n# addition\nprint(x + 1)\nprint(x + y)\nprint(x + xn == 0)\nprint(bool(x + xn))\n\n# subtraction\nprint(x - 1)\nprint(x - y)\nprint(y - x)\nprint(x - x == 0)\nprint(bool(x - x))\n\n# multiplication\nprint(x * 2)\nprint(x * y)\n\n# integer division\nprint(x // 2)\nprint(y // x)\n\n# bit inversion\nprint(~x)\nprint(~(-x))\n\n# left shift\nx = 0x10000000000000000000000\nfor i in range(32):\n    x = x << 1\n    print(x)\n\n# right shift\nx = 0x10000000000000000000000\nfor i in range(32):\n    x = x >> 1\n    print(x)\n\n# left shift of a negative number\nfor i in range(8):\n    print(-10000000000000000000000000 << i)\n    print(-10000000000000000000000001 << i)\n    print(-10000000000000000000000002 << i)\n    print(-10000000000000000000000003 << i)\n    print(-10000000000000000000000004 << i)\n\n# right shift of a negative number\nfor i in range(8):\n    print(-10000000000000000000000000 >> i)\n    print(-10000000000000000000000001 >> i)\n    print(-10000000000000000000000002 >> i)\n    print(-10000000000000000000000003 >> i)\n    print(-10000000000000000000000004 >> i)\n\n# conversion from string\nprint(int(\"123456789012345678901234567890\"))\nprint(int(\"-123456789012345678901234567890\"))\nprint(int(\"123456789012345678901234567890abcdef\", 16))\nprint(int(\"123456789012345678901234567890ABCDEF\", 16))\nprint(int(\"1234567890abcdefghijklmnopqrstuvwxyz\", 36))\n\n# invalid characters in string\ntry:\n    print(int(\"123456789012345678901234567890abcdef\"))\nexcept ValueError:\n    print('ValueError');\ntry:\n    print(int(\"123456789012345678901234567890\\x01\"))\nexcept ValueError:\n    print('ValueError');\n\n# test constant integer with more than 255 chars\nx = 0x84ce72aa8699df436059f052ac51b6398d2511e49631bcb7e71f89c499b9ee425dfbc13a5f6d408471b054f2655617cbbaf7937b7c80cd8865cf02c8487d30d2b0fbd8b2c4e102e16d828374bbc47b93852f212d5043c3ea720f086178ff798cc4f63f787b9c2e419efa033e7644ea7936f54462dc21a6c4580725f7f0e7d1aaaaaaa\nprint(x)\n\n# test parsing ints just on threshold of small to big\n# for 32 bit archs\nx = 1073741823 # small\nx = -1073741823 # small\nx = 1073741824 # big\nx = -1073741824 # big\n# for nan-boxing with 47-bit small ints\nprint(int('0x3fffffffffff', 16)) # small\nprint(int('-0x3fffffffffff', 16)) # small\nprint(int('0x400000000000', 16)) # big\nprint(int('-0x400000000000', 16)) # big\n# for 64 bit archs\nx = 4611686018427387903 # small\nx = -4611686018427387903 # small\nx = 4611686018427387904 # big\nx = -4611686018427387904 # big\n\n# sys.maxsize is a constant mpz, so test it's compatible with dynamic ones\nimport sys\nprint(sys.maxsize + 1 - 1 == sys.maxsize)\n\n# test extraction of big int value via mp_obj_get_int_maybe\nx = 1 << 70\nprint('a' * (x + 4 - x))\n";
