static const char hc_py_333[] = "# This tests small int range for 32-bit machine\n\n# Small ints are variable-length encoded in MicroPython, so first\n# test that encoding works as expected.\n\nprint(0)\nprint(1)\nprint(-1)\n# Value is split in 7-bit \"subwords\", and taking into account that all\n# ints in Python are signed, there're 6 bits of magnitude. So, around 2^6\n# there's \"turning point\"\nprint(63)\nprint(64)\nprint(65)\nprint(-63)\nprint(-64)\nprint(-65)\n# Maximum values of small ints on 32-bit platform\nprint(1073741823)\n# Per python semantics, lexical integer is without a sign (i.e. positive)\n# and '-' is unary minus operation applied to it. That's why -1073741824\n# (min two-complement's negative value) is not allowed.\nprint(-1073741823)\n\n# Operations tests\n\n# compile-time constexprs\nprint(1 + 3)\nprint(3 - 2)\nprint(2 * 3)\nprint(1 & 3)\nprint(1 | 2)\nprint(1 ^ 3)\nprint(+3)\nprint(-3)\nprint(~3)\n\na = 0x3fffff\nprint(a)\na *= 0x10\nprint(a)\na *= 0x10\nprint(a)\na += 0xff\nprint(a)\n# This would overflow\n#a += 1\n\na = -0x3fffff\nprint(a)\na *= 0x10\nprint(a)\na *= 0x10\nprint(a)\na -= 0xff\nprint(a)\n# This still doesn't overflow\na -= 1\nprint(a)\n# This would overflow\n#a -= 1\n\n# negative shifts are not allowed\ntry:\n    a << -1\nexcept ValueError:\n    print(\"ValueError\")\ntry:\n    a >> -1\nexcept ValueError:\n    print(\"ValueError\")\n\n# Shifts to big amounts are undefined behavior in C and is CPU-specific\n\n# These are compile-time constexprs\nprint(1 >> 32)\nprint(1 >> 64)\nprint(1 >> 128)\n\n# These are runtime calcs\na = 1\nprint(a >> 32)\nprint(a >> 64)\nprint(a >> 128)\n";
static const char hc_py_334[] = "try:\n    import io\n\n    io.BytesIO\n    io.BufferedWriter\nexcept (AttributeError, ImportError):\n    print('SKIP')\n    raise SystemExit\n\nbts = io.BytesIO()\nbuf = io.BufferedWriter(bts, 8)\n\nbuf.write(b\"foobar\")\nprint(bts.getvalue())\nbuf.write(b\"foobar\")\n# CPython has different flushing policy, so value below is different\nprint(bts.getvalue())\nbuf.flush()\nprint(bts.getvalue())\nbuf.flush()\nprint(bts.getvalue())\n\n# special case when alloc is a factor of total buffer length\nbts = io.BytesIO()\nbuf = io.BufferedWriter(bts, 1)\nbuf.write(b\"foo\")\nprint(bts.getvalue())\n\n# hashing a BufferedWriter\nprint(type(hash(buf)))\n\n# Test failing flush()\nclass MyIO(io.IOBase):\n    def __init__(self):\n        self.count = 0\n\n    def write(self, buf):\n        self.count += 1\n        if self.count < 3:\n            return None\n        print(\"writing\", buf)\n        return len(buf)\n\n\nbuf = io.BufferedWriter(MyIO(), 8)\n\nbuf.write(b\"foobar\")\n\nfor _ in range(4):\n    try:\n        buf.flush()\n        print(\"flushed\")\n    except OSError:\n        print(\"OSError\")\n";
