static const char hc_py_346[] = "# test user defined iterators\n\n# this class is not iterable\nclass NotIterable:\n    pass\ntry:\n    for i in NotIterable():\n        pass\nexcept TypeError:\n    print('TypeError')\n\n# this class has no __next__ implementation\nclass NotIterable:\n    def __iter__(self):\n        return self\ntry:\n    print(all(NotIterable()))\nexcept TypeError:\n    print('TypeError')\n\nclass MyStopIteration(StopIteration):\n    pass\n\nclass myiter:\n    def __init__(self, i):\n        self.i = i\n\n    def __iter__(self):\n        return self\n\n    def __next__(self):\n        if self.i <= 0:\n            # stop in the usual way\n            raise StopIteration\n        elif self.i == 10:\n            # stop with an argument\n            raise StopIteration(42)\n        elif self.i == 20:\n            # raise a non-stop exception\n            raise TypeError\n        elif self.i == 30:\n            # raise a user-defined stop iteration\n            print('raising MyStopIteration')\n            raise MyStopIteration\n        else:\n            # return the next value\n            self.i -= 1\n            return self.i\n\nfor i in myiter(5):\n    print(i)\n\nfor i in myiter(12):\n    print(i)\n\ntry:\n    for i in myiter(22):\n        print(i)\nexcept TypeError:\n    print('raised TypeError')\n\ntry:\n    for i in myiter(5):\n        print(i)\n        raise StopIteration\nexcept StopIteration:\n    print('raised StopIteration')\n\nfor i in myiter(32):\n    print(i)\n\n# repeat some of the above tests but use tuple() to walk the iterator (tests mp_iternext)\nprint(tuple(myiter(5)))\nprint(tuple(myiter(12)))\nprint(tuple(myiter(32)))\ntry:\n    tuple(myiter(22))\nexcept TypeError:\n    print('raised TypeError')\n";
