static const char hc_py_368[] = "l = [1, 3, 2, 5]\n\nprint(l)\nprint(sorted(l))\nl.sort()\nprint(l)\nprint(l == sorted(l))\n\nprint(sorted(l, key=lambda x: -x))\nl.sort(key=lambda x: -x)\nprint(l)\nprint(l == sorted(l, key=lambda x: -x))\n\nprint(sorted(l, key=lambda x: -x, reverse=True))\nl.sort(key=lambda x: -x, reverse=True)\nprint(l)\nprint(l == sorted(l, key=lambda x: -x, reverse=True))\n\nprint(sorted(l, reverse=True))\nl.sort(reverse=True)\nprint(l)\nprint(l == sorted(l, reverse=True))\n\nprint(sorted(l, reverse=False))\nl.sort(reverse=False)\nprint(l)\nprint(l == sorted(l, reverse=False))\n\n# test large lists (should not stack overflow)\nl = list(range(200))\nl.sort()\nprint(l[0], l[-1])\nl.sort(reverse=True)\nprint(l[0], l[-1])\n\n# test user-defined ordering\nclass A:\n    def __init__(self, x):\n        self.x = x\n    def __lt__(self, other):\n        return self.x > other.x\n    def __repr__(self):\n        return str(self.x)\nl = [A(5), A(2), A(1), A(3), A(4)]\nprint(l)\nl.sort()\nprint(l)\nl.sort(reverse=True)\nprint(l)\n";
