static const char hc_py_382[] = "try:\n    from collections import namedtuple\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\nT = namedtuple(\"Tup\", [\"foo\", \"bar\"])\n# CPython prints fully qualified name, what we don't bother to do so far\n#print(T)\nfor t in T(1, 2), T(bar=1, foo=2):\n    print(t)\n    print(t[0], t[1])\n    print(t.foo, t.bar)\n\n    print(len(t))\n    print(bool(t))\n    print(t + t)\n    print(t * 3)\n\n    print([f for f in t])\n\n    print(isinstance(t, tuple))\n\n    # a NamedTuple can be used as a tuple\n    print(\"(%d, %d)\" % t)\n\n    # Check tuple can compare equal to namedtuple with same elements\n    print(t == (t[0], t[1]), (t[0], t[1]) == t)\n\n# Create using positional and keyword args\nprint(T(3, bar=4))\n\ntry:\n    t[0] = 200\nexcept TypeError:\n    print(\"TypeError\")\ntry:\n    t.bar = 200\nexcept AttributeError:\n    print(\"AttributeError\")\n\ntry:\n    t = T(1)\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    t = T(1, 2, 3)\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    t = T(foo=1)\nexcept TypeError:\n    print(\"TypeError\")\n\ntry:\n    t = T(1, foo=1)\nexcept TypeError:\n    print(\"TypeError\")\n\n# enough args, but kw is wrong\ntry:\n    t = T(1, baz=3)\nexcept TypeError:\n    print(\"TypeError\")\n\n# bad argument for member spec\ntry:\n    namedtuple('T', 1)\nexcept TypeError:\n    print(\"TypeError\")\n\n# Try single string\nT3 = namedtuple(\"TupComma\", \"foo bar\")\nt = T3(1, 2)\nprint(t.foo, t.bar)\n\n# Try tuple\nT4 = namedtuple(\"TupTuple\", (\"foo\", \"bar\"))\nt = T4(1, 2)\nprint(t.foo, t.bar)\n\n# Try single string with comma field separator\n# Not implemented so far\n#T2 = namedtuple(\"TupComma\", \"foo,bar\")\n#t = T2(1, 2)\n\n# Creating an empty namedtuple should not segfault\nT5 = namedtuple(\"TupEmpty\", [])\nt = T5()\nprint(t)\n";
