static const char hc_py_393[] = "# see https://docs.python.org/3/reference/expressions.html#operator-precedence\n\n# '|' is the least binding numeric operator\n\n# '^'\n# OK:  1 | (2 ^ 3) = 1 | 1 = 1\n# BAD: (1 | 2) ^ 3 = 3 ^ 3 = 0\nprint(1 | 2 ^ 3)\n\n# '&'\n# OK:  3 ^ (2 & 1) = 3 ^ 0 = 3\n# BAD: (3 ^ 2) & 1 = 1 & 1 = 1\nprint(3 ^ 2 & 1)\n\n# '<<', '>>'\n# OK:  2 & (3 << 1) = 2 & 6 = 2\n# BAD: (2 & 3) << 1 = 2 << 1 = 4\nprint(2 & 3 << 1)\n# OK:  6 & (4 >> 1) = 6 & 2 = 2\n# BAD: (6 & 4) >> 1 = 2 >> 1 = 1\nprint(6 & 4 >> 1)\n\n# '+', '-'\n# OK:  1 << (1 + 1) = 1 << 2 = 4\n# BAD: (1 << 1) + 1 = 2 + 1 = 3\nprint(1 << 1 + 1)\n\n# '*', '/', '//', '%'\n# OK:  2 + (2 * 2) = 2 + 4 = 6\n# BAD: (2 + 2) * 2 = 4 * 2 = 8\nprint(2 + 2 * 2)\n\n# '+x', '-x', '~x'\n\n# '**'\n# OK:  -(2**2) = -4\n# BAD: (-2)**2 = 4\nprint(-2**2)\n# OK: 2**(-1) = 0.5\nprint(2**-0)\n\n# (expr...)\nprint((2 + 2) * 2)\n";
static const char hc_py_394[] = "try:\n    from collections import OrderedDict\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\nd = OrderedDict([(10, 20), (\"b\", 100), (1, 2)])\nprint(len(d))\nprint(list(d.keys()))\nprint(list(d.values()))\ndel d[\"b\"]\nprint(len(d))\nprint(list(d.keys()))\nprint(list(d.values()))\n\n# access remaining elements after deleting\nprint(d[10], d[1])\n\n# add an element after deleting\nd[\"abc\"] = 123\nprint(len(d))\nprint(list(d.keys()))\nprint(list(d.values()))\n\n# pop an element\nprint(d.popitem())\nprint(len(d))\nprint(list(d.keys()))\nprint(list(d.values()))\n\n# add an element after popping\nd[\"xyz\"] = 321\nprint(len(d))\nprint(list(d.keys()))\nprint(list(d.values()))\n\n# pop until empty\nprint(d.popitem())\nprint(d.popitem())\ntry:\n    d.popitem()\nexcept:\n    print('empty')\n";
