static const char hc_py_407[] = "# test set binary operations\n\nsets = [set(), {1}, {1, 2}, {1, 2, 3}, {2, 3}, {2, 3, 5}, {5}, {7}]\nfor s in sets:\n    for t in sets:\n        print(sorted(s), '|', sorted(t), '=', sorted(s | t))\n        print(sorted(s), '^', sorted(t), '=', sorted(s ^ t))\n        print(sorted(s), '&', sorted(t), '=', sorted(s & t))\n        print(sorted(s), '-', sorted(t), '=', sorted(s - t))\n        u = s.copy()\n        u |= t\n        print(sorted(s), \"|=\", sorted(t), '-->', sorted(u))\n        u = s.copy()\n        u ^= t\n        print(sorted(s), \"^=\", sorted(t), '-->', sorted(u))\n        u = s.copy()\n        u &= t\n        print(sorted(s), \"&=\", sorted(t), \"-->\", sorted(u))\n        u = s.copy()\n        u -= t\n        print(sorted(s), \"-=\", sorted(t), \"-->\", sorted(u))\n\n        print(sorted(s), '==', sorted(t), '=', s == t)\n        print(sorted(s), '!=', sorted(t), '=', s != t)\n        print(sorted(s), '>', sorted(t), '=', s > t)\n        print(sorted(s), '>=', sorted(t), '=', s >= t)\n        print(sorted(s), '<', sorted(t), '=', s < t)\n        print(sorted(s), '<=', sorted(t), '=', s <= t)\n\nprint(set('abc') == 1)\n\n# make sure inplace operators modify the set\n\ns1 = s2 = set('abc')\ns1 |= set('ad')\nprint(s1 is s2, len(s1))\n\ns1 = s2 = set('abc')\ns1 ^= set('ad')\nprint(s1 is s2, len(s1))\n\ns1 = s2 = set('abc')\ns1 &= set('ad')\nprint(s1 is s2, len(s1))\n\ns1 = s2 = set('abc')\ns1 -= set('ad')\nprint(s1 is s2, len(s1))\n\n# RHS must be a set\ntry:\n    print(set('12') >= '1')\nexcept TypeError:\n    print('TypeError')\n\n# RHS must be a set\ntry:\n    print(set('12') <= '123')\nexcept TypeError:\n    print('TypeError')\n\n# unsupported operator\ntry:\n    set('abc') * set('abc')\nexcept TypeError:\n    print('TypeError')\n\n# unsupported operator with RHS not a set\ntry:\n    set('abc') * 2\nexcept TypeError:\n    print('TypeError')\n";
