static const char hc_py_450[] = "# comprehensive functionality test for {} format string\n\nint_tests = False # these take a while\nchar_tests = True\nstr_tests = True\n\ndef test(fmt, *args):\n    print('{:8s}'.format(fmt) + '>' +  fmt.format(*args) + '<')\n\ndef test_fmt(conv, fill, alignment, sign, prefix, width, precision, type, arg):\n    fmt = '{'\n    if conv:\n        fmt += '!'\n        fmt += conv\n    fmt += ':'\n    if alignment:\n        fmt += fill\n        fmt += alignment\n    fmt += sign\n    fmt += prefix\n    fmt += width\n    if precision:\n        fmt += '.'\n        fmt += precision\n    fmt += type\n    fmt += '}'\n    test(fmt,  arg)\n    if fill == '0' and alignment == '=':\n        fmt = '{:'\n        fmt += sign\n        fmt += prefix\n        fmt += width\n        if precision:\n            fmt += '.'\n            fmt += precision\n        fmt += type\n        fmt += '}'\n        test(fmt, arg)\n\nif int_tests:\n    int_nums = (-1234, -123, -12, -1, 0, 1, 12, 123, 1234, True, False)\n    #int_nums = (-12, -1, 0, 1, 12, True, False)\n    for type in ('', 'b', 'd', 'o', 'x', 'X'):\n        for width in ('', '1', '3', '5', '7'):\n            for alignment in ('', '<', '>', '=', '^'):\n                for fill in ('', ' ', '0', '@'):\n                    for sign in ('', '+', '-', ' '):\n                        for prefix in ('', '#'):\n                            for num in int_nums:\n                                test_fmt('', fill, alignment, sign, prefix, width, '', type, num)\n\nif char_tests:\n    for width in ('', '1', '2'):\n        for alignment in ('', '<', '>', '^'):\n            for fill in ('', ' ', '0', '@'):\n                test_fmt('', fill, alignment, '', '', width, '', 'c', 48)\n\nif str_tests:\n    for conv in ('', 'r', 's'):\n        for width in ('', '1', '4', '10'):\n            for alignment in ('', '<', '>', '^'):\n                for fill in ('', ' ', '0', '@'):\n                    for str in ('', 'a', 'bcd', 'This is a test with a longer string'):\n                        test_fmt(conv, fill, alignment, '', '', width, '', 's', str)\n";
