static const char hc_py_484[] = "# test MicroPython-specific features of struct\n\ntry:\n    import struct\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\nclass A():\n    pass\n\n# pack and unpack objects\no = A()\ns = struct.pack(\"<O\", o)\no2 = struct.unpack(\"<O\", s)\nprint(o is o2[0])\n\n# pack can accept less arguments than required for the format spec\nprint(struct.pack('<2I', 1))\n\n# pack and unpack pointer to a string\n# This requires uctypes to get the address of the string and instead of\n# putting this in a dedicated test that can be skipped we simply pass\n# if the import fails.\ntry:\n    import uctypes\n    o = uctypes.addressof('abc')\n    s = struct.pack(\"<S\", o)\n    o2 = struct.unpack(\"<S\", s)\n    assert o2[0] == 'abc'\nexcept ImportError:\n    pass\n";
static const char hc_py_485[] = "# Calling an inherited classmethod\nclass Base:\n\n    @classmethod\n    def foo(cls):\n        print(cls.__name__)\n\ntry:\n    Base.__name__\nexcept AttributeError:\n    print(\"SKIP\")\n    raise SystemExit\n\nclass Sub(Base):\n    pass\n\n\nSub.foo()\n\n# overriding a member and accessing it via a classmethod\n\nclass A(object):\n    foo = 0\n\n    @classmethod\n    def bar(cls):\n        print(cls.foo)\n\n    def baz(self):\n        print(self.foo)\n\nclass B(A):\n    foo = 1\n\nB.bar() # class calling classmethod\nB().bar() # instance calling classmethod\nB().baz() # instance calling normal method\n\n# super inside a classmethod\n# ensure the argument of the super method that is called is the child type\n\n\nclass C:\n    @classmethod\n    def f(cls):\n        print(\"C.f\", cls.__name__)  # cls should be D\n\n    @classmethod\n    def g(cls):\n        print(\"C.g\", cls.__name__)  # cls should be D\n\n\nclass D(C):\n    @classmethod\n    def f(cls):\n        print(\"D.f\", cls.__name__)\n        super().f()\n\n    @classmethod\n    def g(cls):\n        print(\"D.g\", cls.__name__)\n        super(D, cls).g()\n\n\nD.f()\nD.g()\nD().f()\nD().g()\n";
