static const char hc_py_497[] = "# test subclassing a native type and overriding __init__\n\nif not hasattr(object, \"__init__\"):\n    print(\"SKIP\")\n    raise SystemExit\n\n# overriding list.__init__()\nclass L(list):\n    def __init__(self, a, b):\n        super().__init__([a, b])\nprint(L(2, 3))\n\n# with keyword arguments, with star arguments and without because those use different C calls\nclass D(dict):\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\nprint(D())\nprint(D([('a', 1)]))\nprint(D([('a', 1)], a=2, b=3))\nprint(D(a=2, b=3))\n\nclass D(dict):\n    def __init__(self):\n        super().__init__()\nprint(D())\n\nclass D(dict):\n    def __init__(self):\n        super().__init__([])\nprint(D())\n\nclass D(dict):\n    def __init__(self):\n        super().__init__(a=1)\nprint(D())\n\nclass D(dict):\n    def __init__(self):\n        super().__init__([], a=1)\nprint(D())\n\n# inherits implicitly from object\nclass A:\n    def __init__(self):\n        print(\"A.__init__\")\n        super().__init__()\nA()\n\n# inherits explicitly from object\nclass B(object):\n    def __init__(self):\n        print(\"B.__init__\")\n        super().__init__()\nB()\n\n# multiple inheritance with object explicitly mentioned\nclass C:\n    pass\nclass D(C, object):\n    def __init__(self):\n        print('D.__init__')\n        super().__init__()\n    def reinit(self):\n        print('D.foo')\n        super().__init__()\na = D()\na.__init__()\na.reinit()\n\n# call __init__() after object is already init'd\nclass L(list):\n    def reinit(self):\n        super().__init__(range(2))\na = L(range(5))\nprint(a)\na.reinit()\nprint(a)\n";
