static const char hc_py_509[] = "# test sys.tracebacklimit\n\ntry:\n    import sys\n    import io\nexcept ImportError:\n    print(\"SKIP\")\n    raise SystemExit\n\ntry:\n    sys.tracebacklimit = 1000\nexcept AttributeError:\n    print(\"SKIP\")\n    raise SystemExit\n\nif hasattr(sys, \"print_exception\"):\n    print_exception = sys.print_exception\nelse:\n    import traceback\n\n    print_exception = lambda e, f: traceback.print_exception(None, e, sys.exc_info()[2], file=f)\n\n\ndef print_exc(e):\n    buf = io.StringIO()\n    print_exception(e, buf)\n    s = buf.getvalue()\n    for l in s.split(\"\\n\"):\n        # Remove filename.\n        if l.startswith(\"  File \"):\n            l = l.split('\"')\n            print(l[0], l[2])\n        # MPy and CPy tracebacks differ in that CPy prints a source line for\n        # each traceback entry.  In this case, we know that offending line\n        # has 4-space indent, so filter it out.\n        elif not l.startswith(\"    \"):\n            print(l)\n\n\ndef f0():\n    raise ValueError(\"value\")\n\n\ndef f1():\n    f0()\n\n\ndef f2():\n    f1()\n\n\ndef f3():\n    f2()\n\n\ndef ftop():\n    try:\n        f3()\n    except ValueError as er:\n        print_exc(er)\n\n\nftop()\n\nfor limit in range(4, -2, -1):\n    print(\"limit\", limit)\n    sys.tracebacklimit = limit\n    ftop()\n\n\n# test deleting the attribute\nprint(hasattr(sys, \"tracebacklimit\"))\ndel sys.tracebacklimit\nprint(hasattr(sys, \"tracebacklimit\"))\n";
