static const char hc_py_521[] = "print(\"noexc-finally\")\ntry:\n    print(\"try\")\nfinally:\n    print(\"finally\")\n\nprint(\"noexc-finally-finally\")\ntry:\n    print(\"try1\")\n    try:\n        print(\"try2\")\n    finally:\n        print(\"finally2\")\nfinally:\n    print(\"finally1\")\nprint()\n\nprint(\"noexc-finally-func-finally\")\ndef func2():\n    try:\n        print(\"try2\")\n    finally:\n        print(\"finally2\")\n\ntry:\n    print(\"try1\")\n    func2()\nfinally:\n    print(\"finally1\")\nprint()\n\n\nprint(\"exc-finally-except\")\ntry:\n    print(\"try1\")\n    try:\n        print(\"try2\")\n        foo()\n    except:\n        print(\"except2\")\nfinally:\n    print(\"finally1\")\nprint()\n\nprint(\"exc-finally-except-filter\")\ntry:\n    print(\"try1\")\n    try:\n        print(\"try2\")\n        foo()\n    except NameError:\n        print(\"except2\")\nfinally:\n    print(\"finally1\")\nprint()\n\n\nprint(\"exc-except-finally-finally\")\ntry:  # top-level catch-all except to not fail script\n    try:\n        print(\"try1\")\n        try:\n            print(\"try2\")\n            foo()\n        finally:\n            print(\"finally2\")\n    finally:\n        print(\"finally1\")\nexcept:\n    print(\"catch-all except\")\nprint()\n\n# case where a try-except within a finally cancels the exception\nprint(\"exc-finally-subexcept\")\ntry:\n    print(\"try1\")\nfinally:\n    try:\n        print(\"try2\")\n        foo\n    except:\n        print(\"except2\")\n    print(\"finally1\")\nprint()\n\n# case where exception is raised after a finally has finished (tests that the finally doesn't run again)\ndef func():\n    try:\n        print(\"try\")\n    finally:\n        print(\"finally\")\n    foo\ntry:\n    func()\nexcept:\n    print(\"except\")\n";
static const char hc_py_522[] = "# check that the Python stack does not overflow when the finally\n# block itself uses more stack than the rest of the function\ndef f1(a, b):\n    pass\ndef test1():\n    val = 1\n    try:\n        raise ValueError()\n    finally:\n        f1(2, 2) # use some stack\n        print(val) # check that the local variable is the same\ntry:\n    test1()\nexcept ValueError:\n    pass\n\n# same as above but with 3 args instead of 2, to use an extra stack entry\ndef f2(a, b, c):\n    pass\ndef test2():\n    val = 1\n    try:\n        raise ValueError()\n    finally:\n        f2(2, 2, 2) # use some stack\n        print(val) # check that the local variable is the same\ntry:\n    test2()\nexcept ValueError:\n    pass\n";
static const char hc_py_523[] = "# test break within (nested) finally\n\n# basic case with break in finally\ndef f():\n    for _ in range(2):\n        print(1)\n        try:\n            pass\n        finally:\n            print(2)\n            break\n            print(3)\n        print(4)\n    print(5)\nf()\n\n# where the finally swallows an exception\ndef f():\n    lst = [1, 2, 3]\n    for x in lst:\n        print('a', x)\n        try:\n            raise Exception\n        finally:\n            print(1)\n            break\n        print('b', x)\nf()\n\n# basic nested finally with break in inner finally\ndef f():\n    for i in range(2):\n        print('iter', i)\n        try:\n            raise TypeError\n        finally:\n            print(1)\n            try:\n                raise ValueError\n            finally:\n                break\nprint(f())\n\n# similar to above but more nesting\ndef f():\n    for i in range(2):\n        try:\n            raise ValueError\n        finally:\n            print(1)\n            try:\n                raise TypeError\n            finally:\n                print(2)\n                try:\n                    pass\n                finally:\n                    break\nprint(f())\n\n# lots of nesting\ndef f():\n    for i in range(2):\n        try:\n            raise ValueError\n        finally:\n            print(1)\n            try:\n                raise TypeError\n            finally:\n                print(2)\n                try:\n                    raise Exception\n                finally:\n                    break\nprint(f())\n\n# basic case combined with try-else\ndef f(arg):\n    for _ in range(2):\n        print(1)\n        try:\n            if arg == 1:\n                raise ValueError\n            elif arg == 2:\n                raise TypeError\n        except ValueError:\n            print(2)\n        else:\n            print(3)\n        finally:\n            print(4)\n            break\n            print(5)\n        print(6)\n    print(7)\nf(0) # no exception, else should execute\nf(1) # exception caught, else should be skipped\nf(2) # exception not caught, finally swallows exception, else should be skipped\n";
