static const char hc_py_526[] = "# Test various loop types, some may be implemented/optimized differently\nwhile True:\n    try:\n        break\n    finally:\n        print('finally 1')\n\n\nfor i in [1, 5, 10]:\n    try:\n        continue\n    finally:\n        print('finally 2')\n\nfor i in range(3):\n    try:\n        continue\n    finally:\n        print('finally 3')\n\n# Multi-level\nfor i in range(4):\n    print(i)\n    try:\n        while True:\n            try:\n                try:\n                    break\n                finally:\n                    print('finally 1')\n            finally:\n                print('finally 2')\n        print('here')\n    finally:\n        print('finnaly 3')\n\n# break from within try-finally, within for-loop\nfor i in [1]:\n    try:\n        print(i)\n        break\n    finally:\n        print('finally 4')\n\n# Test unwind-jump where there is nothing in the body of the try or finally.\n# This checks that the bytecode emitter allocates enough stack for the unwind.\nfor i in [1]:\n    try:\n        break\n    finally:\n        pass\n\n# The following test checks that the globals dict is valid after a call to a\n# function that has an unwind jump.\n# There was a bug where an unwind jump would trash the globals dict upon return\n# from a function, because it used the Python-stack incorrectly.\ndef f():\n    for i in [1]:\n        try:\n            break\n        finally:\n            pass\ndef g():\n    global global_var\n    f()\n    print(global_var)\nglobal_var = 'global'\ng()\n";
static const char hc_py_527[] = "def func1():\n    try:\n        return \"it worked\"\n    finally:\n        print(\"finally 1\")\n\nprint(func1())\n\n\ndef func2():\n    try:\n        return \"it worked\"\n    finally:\n        print(\"finally 2\")\n\ndef func3():\n    try:\n        s = func2()\n        return s + \", did this work?\"\n    finally:\n        print(\"finally 3\")\n\nprint(func3())\n\n# for loop within try-finally\ndef f():\n    try:\n        for i in [1, 2]:\n            return i\n    finally:\n        print('finally')\nprint(f())\n\n# multiple for loops within try-finally\ndef f():\n    try:\n        for i in [1, 2]:\n            for j in [3, 4]:\n                return (i, j)\n    finally:\n        print('finally')\nprint(f())\n\n# multiple for loops and nested try-finally's\ndef f():\n    try:\n        for i in [1, 2]:\n            for j in [3, 4]:\n                try:\n                    for k in [5, 6]:\n                        for l in [7, 8]:\n                            return (i, j, k, l)\n                finally:\n                    print('finally 2')\n    finally:\n        print('finally 1')\nprint(f())\n\n# multiple for loops that are optimised, and nested try-finally's\ndef f():\n    try:\n        for i in range(1, 3):\n            for j in range(3, 5):\n                try:\n                    for k in range(5, 7):\n                        for l in range(7, 9):\n                            return (i, j, k, l)\n                finally:\n                    print('finally 2')\n    finally:\n        print('finally 1')\nprint(f())\n\n# the finally block uses a lot of Python stack and then a local is accessed\n# (tests that the use of the stack doesn't clobber the local)\ndef f(x):\n    try:\n        return x\n    finally:\n        print(2, 3, 4, 5, 6)\n        print(x)\nprint(f(1))\n";
static const char hc_py_528[] = "# test 'return' within the finally block\n# it should swallow the exception\n\n# simple case\ndef f():\n    try:\n        raise ValueError()\n    finally:\n        print('finally')\n        return 0\n    print('got here')\nprint(f())\n\n# nested, return in outer\ndef f():\n    try:\n        try:\n            raise ValueError\n        finally:\n            print('finally 1')\n        print('got here')\n    finally:\n        print('finally 2')\n        return 2\n    print('got here')\nprint(f())\n\n# nested, return in inner\ndef f():\n    try:\n        try:\n            raise ValueError\n        finally:\n            print('finally 1')\n            return 1\n        print('got here')\n    finally:\n        print('finally 2')\n    print('got here')\nprint(f())\n\n# nested, return in inner and outer\ndef f():\n    try:\n        try:\n            raise ValueError\n        finally:\n            print('finally 1')\n            return 1\n        print('got here')\n    finally:\n        print('finally 2')\n        return 2\n    print('got here')\nprint(f())\n\n# nested with reraise\ndef f():\n    try:\n        try:\n            raise ValueError\n        except:\n            raise\n        print('got here')\n    finally:\n        print('finally')\n        return 0\n    print('got here')\nprint(f())\n\n# triple nesting with reraise\ndef f():\n    try:\n        try:\n            try:\n                raise ValueError\n            except:\n                raise\n        except:\n            raise\n    finally:\n        print('finally')\n        return 0\nprint(f())\n\n# exception when matching exception\ndef f():\n    try:\n        raise ValueError\n    except NonExistingError:\n        pass\n    finally:\n        print('finally')\n        return 0\nprint(f())\n\n# raising exception class, not instance\ndef f():\n    try:\n        raise ValueError\n    finally:\n        print('finally')\n        return 0\nprint(f())\n";
static const char hc_py_529[] = "# test 'return' within the finally block, with nested finally's\n# only inactive finally's should be executed, and only once\n\n# basic nested finally's, the print should only be executed once\ndef f():\n    try:\n        raise TypeError\n    finally:\n        print(1)\n        try:\n            raise ValueError\n        finally:\n            return 42\nprint(f())\n\n# similar to above but more nesting\ndef f():\n    try:\n        raise ValueError\n    finally:\n        print(1)\n        try:\n            raise TypeError\n        finally:\n            print(2)\n            try:\n                pass\n            finally:\n                return 42\nprint(f())\n\n# similar to above but even more nesting\ndef f():\n    try:\n        raise ValueError\n    finally:\n        print(1)\n        try:\n            raise TypeError\n        finally:\n            print(2)\n            try:\n                raise Exception\n            finally:\n                print(3)\n                return 42\nprint(f())\n\n# upon return some try's are active, some finally's are active, some inactive\ndef f():\n    try:\n        try:\n            pass\n        finally:\n            print(2)\n            return 42\n    finally:\n        print(1)\nprint(f())\n\n# same as above but raise instead of pass\ndef f():\n    try:\n        try:\n            raise ValueError\n        finally:\n            print(2)\n            return 42\n    finally:\n        print(1)\nprint(f())\n\n# upon return exception stack holds: active finally, inactive finally, active finally\ndef f():\n    try:\n        raise Exception\n    finally:\n        print(1)\n        try:\n            try:\n                pass\n            finally:\n                print(3)\n                return 42\n        finally:\n            print(2)\nprint(f())\n\n# same as above but raise instead of pass in innermost try block\ndef f():\n    try:\n        raise Exception\n    finally:\n        print(1)\n        try:\n            try:\n                raise Exception\n            finally:\n                print(3)\n                return 42\n        finally:\n            print(2)\nprint(f())\n";
static const char hc_py_530[] = "# test try-finally with return, where unwinding return has to go through\n# another try-finally which may affect the behaviour of the return\n\n# case where a simple try-finally executes during an unwinding return\ndef f(x):\n    try:\n        try:\n            if x:\n                return 42\n        finally:\n            try:\n                print(1)\n            finally:\n                print(2)\n            print(3)\n        print(4)\n    finally:\n        print(5)\nprint(f(0))\nprint(f(1))\n\n# case where an unwinding return is replaced by another one\ndef f(x):\n    try:\n        try:\n            if x:\n                return 42\n        finally:\n            try:\n                print(1)\n                return 43\n            finally:\n                print(2)\n            print(3)\n        print(4)\n    finally:\n        print(5)\nprint(f(0))\nprint(f(1))\n\n# case where an unwinding return is cancelled by an exception\ndef f(x):\n    try:\n        try:\n            if x:\n                return 42\n        finally:\n            try:\n                print(1)\n                raise ValueError # cancels any active return\n            finally:\n                print(2)\n            print(3)\n        print(4)\n    finally:\n        print(5)\ntry:\n    print(f(0))\nexcept:\n    print('caught')\ntry:\n    print(f(1))\nexcept:\n    print('caught')\n\n# case where an unwinding return is cancelled then resumed\ndef f(x):\n    try:\n        try:\n            if x:\n                return 42\n        finally:\n            try:\n                print(1)\n                raise Exception # cancels any active return\n            except: # cancels the exception and resumes any active return\n                print(2)\n            print(3)\n        print(4)\n    finally:\n        print(5)\nprint(f(0))\nprint(f(1))\n";
